  RFQ,
  RFQItem,
  RFQResponse,
  RFQListResponse,
  RFQResponseListResponse,
  Document,
  DocumentListResponse,
  DocumentUploadResponse,
  DocumentVersionResponse,
  ComplianceChecklist,
  ComplianceChecklistListResponse,
  ComplianceTemplateListResponse,
  InquiryListResponse,
  Inquiry,
  ServiceAgreementListResponse,
  ServiceAgreement,
  TokenListResponse,
  Token,
  DRNListResponse,
  DRN,
  TimeLogListResponse,
  TimeLog,
  SustainabilityListResponse,
  Sustainability,
} from "@/types/api";
import { getAccessToken, getRefreshToken, setTokens, clearTokens } from "./auth";

class ApiError extends Error {
  constructor(public status: number, public body: unknown) {
    super(`API Error: ${status}`);
    this.name = "ApiError";
  }
}

async function request<T>(
  path: string,
  options: RequestInit = {}
): Promise<T> {
  const token = getAccessToken();
  const headers: Record<string, string> = {
    ...(options.headers as Record<string, string>),
  };
  if (token) {
    headers["Authorization"] = `Bearer ${token}`;
  }

  const isFormData = options.body instanceof FormData;
  if (!isFormData && !headers["Content-Type"]) {
    headers["Content-Type"] = "application/json";
  }

  let response = await fetch(path, { ...options, headers });

  if (response.status === 401) {
    const refresh = getRefreshToken();
    if (refresh) {
      try {
        const refreshResponse = await fetch("/api/auth/refresh", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ refresh_token: refresh }),
        });
        if (refreshResponse.ok) {
          const tokens: AccessTokenResponse = await refreshResponse.json();
          setTokens(tokens.access_token, refresh);
          headers["Authorization"] = `Bearer ${tokens.access_token}`;
          response = await fetch(path, { ...options, headers });
        } else {
          clearTokens();
          window.location.href = "/login";
          throw new ApiError(401, null);
        }
      } catch {
        clearTokens();
        window.location.href = "/login";
        throw new ApiError(401, null);
      }
    }
  }

  if (!response.ok) {
    const body = await response.json().catch(() => null);
    throw new ApiError(response.status, body);
  }

  return response.json();
}

export const api = {
  login: (data: LoginRequest) =>
    request<TokenResponse>("/api/auth/login", {
      method: "POST",
      body: JSON.stringify(data),
    }),

  refresh: (refreshToken: string) =>
    request<AccessTokenResponse>("/api/auth/refresh", {
      method: "POST",
      body: JSON.stringify({ refresh_token: refreshToken }),
    }),

  logout: () =>
    request<MessageResponse>("/api/auth/logout", { method: "POST" }),

  me: () => request<User>("/api/auth/me"),

  listUsers: (params?: { page?: number; page_size?: number; q?: string; role?: string }) => {
    const searchParams = new URLSearchParams();
    if (params?.page) searchParams.set("page", String(params.page));
    if (params?.page_size) searchParams.set("page_size", String(params.page_size));
    if (params?.q) searchParams.set("q", params.q);
    if (params?.role) searchParams.set("role", params.role);
    const query = searchParams.toString();
    return request<UserListResponse>(`/api/users${query ? `?${query}` : ""}`);
  },

  createUser: (data: UserCreate) =>
    request<User>("/api/users", {
      method: "POST",
      body: JSON.stringify(data),
    }),

