import { useState, useEffect } from "react";
import { zodResolver } from "@hookform/resolvers/zod";
import { useForm } from "react-hook-form";
import { z } from "zod";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { MetricType } from "@/types/marketing";

const instagramMetricSchema = z.object({
  metric_id: z.string().min(1, "Metric ID is required"),
  period_yyyymm: z.string().min(6, "Period (YYYYMM) is required"),
  followers_start: z.number().min(0),
  followers_end: z.number().min(0),
  followers_net_add: z.number().min(0).optional(),
  impressions: z.number().min(0),
  reach: z.number().min(0),
  profile_visits: z.number().min(0),
  likes: z.number().min(0),
  comments: z.number().min(0),
  shares: z.number().min(0),
  saves: z.number().min(0),
  engagement_rate: z.number().min(0).max(1),
  posts_count: z.number().min(0),
  reels_count: z.number().min(0),
  stories_count: z.number().min(0),
  website_clicks: z.number().min(0),
  inbound_dms: z.number().min(0),
  leads_count: z.number().min(0),
  inquiry_count: z.number().min(0),
  notes: z.string().optional(),
});

const linkedinMetricSchema = z.object({
  metric_id: z.string().min(1, "Metric ID is required"),
  period_yyyymm: z.string().min(6, "Period (YYYYMM) is required"),
  followers_start: z.number().min(0),
  followers_end: z.number().min(0),
  followers_net_add: z.number().min(0).optional(),
  impressions: z.number().min(0),
  reach: z.number().min(0),
  profile_views: z.number().min(0),
  reactions: z.number().min(0),
  comments: z.number().min(0),
  reposts: z.number().min(0),
  engagement_rate: z.number().min(0).max(1),
  posts_count: z.number().min(0),
  articles_count: z.number().min(0),
  videos_count: z.number().min(0),
  website_clicks: z.number().min(0),
  inbound_dms: z.number().min(0),
  leads_count: z.number().min(0),
  inquiry_count: z.number().min(0),
  notes: z.string().optional(),
});

const websiteMetricSchema = z.object({
  metric_id: z.string().min(1, "Metric ID is required"),
  period_yyyymm: z.string().min(6, "Period (YYYYMM) is required"),
  sessions: z.number().min(0),
  users: z.number().min(0),
  new_users: z.number().min(0),
  returning_users: z.number().min(0),
  page_views: z.number().min(0),
  pages_per_session: z.number().min(0),
  avg_session_duration_sec: z.number().min(0),
  bounce_rate: z.number().min(0).max(1),
  direct_traffic_pct: z.number().min(0).max(1),
  organic_traffic_pct: z.number().min(0).max(1),
  social_traffic_pct: z.number().min(0).max(1),
  referral_traffic_pct: z.number().min(0).max(1),
  paid_traffic_pct: z.number().min(0).max(1),
  contact_form_submissions: z.number().min(0),
  consultation_requests: z.number().min(0),
  downloads_count: z.number().min(0),
  call_clicks: z.number().min(0),
  leads_count: z.number().min(0),
  inquiry_count: z.number().min(0),
  projects_converted: z.number().min(0),
  notes: z.string().optional(),
});

type InstagramFormData = z.infer<typeof instagramMetricSchema>;
type LinkedInFormData = z.infer<typeof linkedinMetricSchema>;
type WebsiteFormData = z.infer<typeof websiteMetricSchema>;

interface MetricFormProps {
  metricType: MetricType;
  initialData?: Partial<InstagramFormData | LinkedInFormData | WebsiteFormData>;
  onSubmit: (data: InstagramFormData | LinkedInFormData | WebsiteFormData) => Promise<void>;
  onCancel?: () => void;
  isLoading?: boolean;
}

export function MetricForm({ metricType, initialData, onSubmit, onCancel, isLoading }: MetricFormProps) {
  const getSchema = () => {
    switch (metricType) {
      case "instagram": return instagramMetricSchema;
      case "linkedin": return linkedinMetricSchema;
      case "website": return websiteMetricSchema;
      default: return instagramMetricSchema;
    }
  };

  const form = useForm<InstagramFormData | LinkedInFormData | WebsiteFormData>({
    resolver: zodResolver(getSchema()),
    defaultValues: initialData,
  });

  const handleSubmit = async (data: InstagramFormData | LinkedInFormData | WebsiteFormData) => {
    await onSubmit(data);
  };

  const getFields = () => {
    switch (metricType) {
      case "instagram":
        return [
          { name: "metric_id", label: "Metric ID", type: "text" },
          { name: "period_yyyymm", label: "Period (YYYYMM)", type: "text" },
          { name: "followers_start", label: "Followers Start", type: "number" },
          { name: "followers_end", label: "Followers End", type: "number" },
          { name: "followers_net_add", label: "Net Add", type: "number" },
          { name: "impressions", label: "Impressions", type: "number" },
          { name: "reach", label: "Reach", type: "number" },
          { name: "profile_visits", label: "Profile Visits", type: "number" },
          { name: "likes", label: "Likes", type: "number" },
          { name: "comments", label: "Comments", type: "number" },
          { name: "shares", label: "Shares", type: "number" },
          { name: "saves", label: "Saves", type: "number" },
          { name: "engagement_rate", label: "Engagement Rate", type: "number" },
        ];
      case "linkedin":
        return [
          { name: "metric_id", label: "Metric ID", type: "text" },
          { name: "period_yyyymm", label: "Period (YYYYMM)", type: "text" },
          { name: "followers_start", label: "Followers Start", type: "number" },
          { name: "followers_end", label: "Followers End", type: "number" },
          { name: "followers_net_add", label: "Net Add", type: "number" },
          { name: "impressions", label: "Impressions", type: "number" },
          { name: "reach", label: "Reach", type: "number" },
          { name: "profile_views", label: "Profile Views", type: "number" },
          { name: "reactions", label: "Reactions", type: "number" },
          { name: "comments", label: "Comments", type: "number" },
        ];
      case "website":
        return [
          { name: "metric_id", label: "Metric ID", type: "text" },
          { name: "period_yyyymm", label: "Period (YYYYMM)", type: "text" },
          { name: "sessions", label: "Sessions", type: "number" },
          { name: "users", label: "Users", type: "number" },
          { name: "page_views", label: "Page Views", type: "number" },
          { name: "bounce_rate", label: "Bounce Rate", type: "number" },
          { name: "contact_form_submissions", label: "Contact Forms", type: "number" },
          { name: "consultation_requests", label: "Consultations", type: "number" },
          { name: "leads_count", label: "Leads", type: "number" },
          { name: "inquiry_count", label: "Inquiries", type: "number" },
        ];
      default:
        return [];
    }
  };

  return (
    <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle>Create {metricType.charAt(0).toUpperCase() + metricType.slice(1)} Metric</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          {getFields().map((field) => (
            <div key={field.name} className="space-y-2">
              <Label htmlFor={field.name}>{field.label}</Label>
              <Input
                id={field.name}
                type={field.type}
                {...form.register(field.name, { valueAsNumber: field.type === "number" })}
              />
              {form.formState.errors[field.name as keyof typeof form.formState.errors] && (
                <p className="text-sm text-red-500">
                  {(form.formState.errors[field.name as keyof typeof form.formState.errors] as { message: string }).message}
                </p>
              )}
            </div>
          ))}

          <div className="space-y-2">
            <Label htmlFor="notes">Notes</Label>
            <Textarea id="notes" {...form.register("notes")} />
          </div>
        </CardContent>
      </Card>

      <div className="flex gap-3 justify-end">
        {onCancel && (
          <Button type="button" variant="outline" onClick={onCancel}>
            Cancel
          </Button>
        )}
        <Button type="submit" disabled={isLoading}>
          {isLoading ? "Saving..." : "Save"}
        </Button>
      </div>
    </form>
  );
}

import { MetricList } from "@/components/marketing/MetricList";

export function MarketingPage() {
  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h1 className="text-3xl font-bold tracking-tight">Marketing Metrics</h1>
      </div>

      <div className="grid gap-6">
        <MetricList metricType="instagram" metricTypeLabel="Instagram Metrics" listKey="instagram-metrics" />
        <MetricList metricType="linkedin" metricTypeLabel="LinkedIn Metrics" listKey="linkedin-metrics" />
        <MetricList metricType="website" metricTypeLabel="Website Metrics" listKey="website-metrics" />
      </div>
    </div>
  );
}

import { MetricListResponse, InstagramMetric, LinkedInMetric, WebsiteMetric, Metric } from "@/types/marketing";

export type { InstagramMetric, LinkedInMetric, WebsiteMetric, Metric };

const API_BASE_URL = "/api";

class MarketingApiError extends Error {
  constructor(public status: number, public body: unknown) {
    super(`Marketing API Error: ${status}`);
    this.name = "MarketingApiError";
  }
}

async function marketingRequest<T>(
  path: string,
  options: RequestInit = {}
): Promise<T> {
  const token = localStorage.getItem("access_token");
  const headers: Record<string, string> = {
    ...(options.headers as Record<string, string>),
  };
  if (token) {
    headers["Authorization"] = `Bearer ${token}`;
  }

  if (!headers["Content-Type"] && !(options.body instanceof FormData)) {
    headers["Content-Type"] = "application/json";
  }

  let response = await fetch(path, { ...options, headers });

  if (response.status === 401) {
    const refresh = localStorage.getItem("refresh_token");
    if (refresh) {
      try {
        const refreshResponse = await fetch(`${API_BASE_URL}/auth/refresh`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ refresh_token: refresh }),
        });
        if (refreshResponse.ok) {
          const tokens = await refreshResponse.json();
          localStorage.setItem("access_token", tokens.access_token);
          headers["Authorization"] = `Bearer ${tokens.access_token}`;
          response = await fetch(path, { ...options, headers });
        } else {
          localStorage.removeItem("access_token");
          localStorage.removeItem("refresh_token");
          window.location.href = "/login";
          throw new MarketingApiError(401, null);
        }
      } catch {
        localStorage.removeItem("access_token");
        localStorage.removeItem("refresh_token");
        window.location.href = "/login";
        throw new MarketingApiError(401, null);
      }
    }
  }

  if (!response.ok) {
    const body = await response.json().catch(() => null);
    throw new MarketingApiError(response.status, body);
  }

  return response.json();
}

export const marketingApi = {
  listMetrics: async (
    metricType: "instagram" | "linkedin" | "website",
    params?: { page?: number; page_size?: number; q?: string }
  ): Promise<MetricListResponse> => {
    const searchParams = new URLSearchParams();
    if (params?.page) searchParams.set("page", String(params.page));
    if (params?.page_size) searchParams.set("page_size", String(params.page_size));
    if (params?.q) searchParams.set("q", params.q);
    const query = searchParams.toString();
    const endpoint = `/api/${metricType}-metrics${query ? `?${query}` : ""}`;
    const response = await marketingRequest<MetricListResponse>(endpoint, {
      method: "GET",
    });
    return response;
  },

  createMetric: async (
    metricType: "instagram" | "linkedin" | "website",
    data: Record<string, unknown>
  ): Promise<Metric> => {
    const endpoint = `/api/${metricType}-metrics`;
    const response = await marketingRequest<Metric>(endpoint, {
      method: "POST",
      body: JSON.stringify(data),
    });
    return response;
  },

  getMetric: async (metricType: "instagram" | "linkedin" | "website", id: string): Promise<Metric> => {
    const endpoint = `/api/${metricType}-metrics/${id}`;
    const response = await marketingRequest<Metric>(endpoint);
    return response;
  },

  updateMetric: async (
    metricType: "instagram" | "linkedin" | "website",
    id: string,
    data: Record<string, unknown>
  ): Promise<Metric> => {
    const endpoint = `/api/${metricType}-metrics/${id}`;
    const response = await marketingRequest<Metric>(endpoint, {
      method: "PATCH",
      body: JSON.stringify(data),
    });
    return response;
  },

  deleteMetric: async (metricType: "instagram" | "linkedin" | "website", id: string): Promise<void> => {
    const endpoint = `/api/${metricType}-metrics/${id}`;
    await marketingRequest<void>(endpoint, {
      method: "DELETE",
    });
  },
};

